records=[]
def add(id,name,regions,type,classification,places,summary,caution,aliases=None,context=None,question=None):
    project='project-ajk' if type!='clan' else 'project-clans'
    aliases=aliases or []
    claims=[]
    if context:
        claims.append({'title':'Recorded usage','text':context['text'],'status':'context','source':context['source'],'locator':context['locator']})
    claims.append({'title':'Classification and locality scope','text':caution,'status':'verify','source':project,'locator':name+' panel and the poster footer'})
    records.append({'id':id,'name':name,'regions':regions,'type':type,'classification':classification,'aliases':aliases,'locations':places,'locationSource':project,'summary':summary,'caution':caution,'hasContext':bool(context),'claims':claims,'sourceIds':list(dict.fromkeys(([context['source']] if context else [])+[project])),'question':question or 'Find a district or family-specific reference for the classification and locality examples before using them as historical facts.'})

def alias(name,kind='Project spelling',note='The project pairs these spellings. This is a search link, not proof of shared ancestry.'):
    return {'name':name,'kind':kind,'note':note}
def book(text,locator): return {'source':'ibbetson','text':text,'locator':locator}
def hrw(text): return {'source':'hrw','text':text,'locator':'II Background, Culture and ethnicity'}

add('gujjar','Gujjar',['kashmir'],'community','Community identity in the AJK directory',['Muzaffarabad division','Poonch division','Mirpur division'],'The AJK project directory includes Gujjar as a community identity. An independent regional account also names Gujjars in AJK.','The poster examples span divisions. They do not establish exclusive areas, current population size or one genealogy.',[alias('Gujjars','Spelling in regional source')],hrw('HRW names Gujjars among AJK biradaris.'),'Verify district-specific locality examples. Keep any population estimate dated and attributed.')
add('jat','Jat',['kashmir'],'community','Community identity in the AJK directory',['Mirpur','Bhimber','Kotli'],'Jat appears in the AJK directory, paired with Jutt. The independent context used here concerns Mirpuri Jats.','The regional reference supports Mirpuri usage. Bhimber and Kotli remain locality examples from the project poster.',[alias('Jutt'),alias('Jats','Plural in regional source')],hrw('HRW describes Mirpuri Jats in southern AJK.'),'Find a local reference for each district. Do not treat the wider Jat identity as one clan.')
add('rajput','Rajput',['kashmir'],'community','Broader identity in the AJK directory',['Across AJK'],'The project uses Rajput as a broader community identity. Individual clan records are catalogued separately.','The broad label does not settle the affiliation or genealogy of every named clan. The collection follows the supplied poster scope.',[alias('Rajputs','Plural in regional source')],hrw('HRW describes Rajputs across AJK.'),'Qualify each clan association individually instead of applying the broad label to every family.')
