for id,name,regions,places,classification,aliases,context,caution in clans:
    add(id,name,regions,'clan',classification,places,f'{name} appears in the project clan chart. '+('An independent historical passage provides context for the recorded name or classification.' if context else 'This entry currently serves as a research lead.'),caution,aliases,context)

book_metadata = enrich(records, sources)
payload={'version':2,'checkedOn':'8 October 2026','scope':'Selected Pakistani Punjab and AJK records, with dated examples from wider historical Punjab','sources':sources,'records':records,'book':book_metadata}
(ROOT/'dist/data.js').write_text('window.COLLECTION = '+json.dumps(payload,ensure_ascii=False,indent=2)+';\n',encoding='utf-8',newline='\n')
print(f'Prepared {len(records)} records and {len(sources)} source items')
